import{d as c,C as t,o as u,c as b,j as a,a as s,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第七十七章","description":"从张弓的高低余缺读天人之道，辨奉天下、为而不恃与不欲见贤。","frontmatter":{"title":"道德经第七十七章","description":"从张弓的高低余缺读天人之道，辨奉天下、为而不恃与不欲见贤。","category":"guide","aliases":["道德经第七十七章","老子第七十七章","dao de jing chapter 77"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-77.md","filePath":"daoism/dao-de-jing/chapter-77.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-77.md"},_=c({...g,setup(x){const o=[{id:"drawing-the-bow",label:"天之道，其犹张弓与",showLabel:!0,sentences:[["天之道，其犹",{text:"张",glossary:"zhang-expand"},"弓与？高者",{text:"抑",glossary:"yi-press-down"},"之，下者",{text:"举",glossary:"ju-raise"},"之；有余者",{text:"损",glossary:"sun-reduce"},"之，不足者补之。"]],note:["【白话】天的运行之道，大概像张弓吧？高的压低，低的举高；多余的减去，不足的补上。张弓的高低调整，引出余缺的调节。","【读法】与在问句末表疑问，读 yú。张弓是本章取象，不把它延伸为所有自然现象或现代经济运行都会自动均衡的定律。"]},{id:"heaven-and-rebalancing",label:"天之道，损有余而补不足",showLabel:!0,sentences:[["天之道，",{text:"损",glossary:"sun-reduce"},"有余而补不足。"]],note:["【白话】天之道，是减损有余的一面，补给不足的一面。这句从张弓的形象中抽出所要强调的方向。","【读法】后文以此对照人间取用，重点在余缺如何流转；现代的分配标准与制度如何制定，需要另作论证。"]},{id:"human-extraction",label:"人之道则不然",showLabel:!0,sentences:[["人之道则不然，",{text:"损",glossary:"sun-reduce"},"不足以",{text:"奉",glossary:"feng-offer"},"有余。"]],note:["【白话】人的行事之道却不是这样，反而削减不足者所拥有的，去供奉已经有余者。这里揭示一种与前述方向相反的人间取用。","【王弼注择要】王注说「如人之量，则各有其身，不得相均」，以各执其身的局限说明差别。","【读法】人之道在此指出所批评的现实倾向，不是断言每个人永远只能损不足。下句随即提出有道者的另一种可能。"]},{id:"offering-surplus-to-all",label:"孰能有余以奉天下",showLabel:!0,sentences:[["孰能有余以",{text:"奉",glossary:"feng-offer"},"天下？唯有道者。"]],note:["【白话】谁能拿有余来供给天下？只有有道的人能够如此。奉的对象从有余者转为天下，回应前面的失衡。","【王弼注择要】承上说明与天地合德，王注提出「无身无私乎自然」。","【读法】无私在此指不把一己取用作为中心，不能拿来要求某一群体承担无限牺牲。"]},{id:"acting-without-claiming",label:"是以圣人为而不恃",showLabel:!0,sentences:[["是以圣人为而不",{text:"恃",glossary:"shi-rely"},"，功成而不",{text:"处",glossary:"chu-dwell"},"，"]],note:["【白话】所以圣人有所作为，却不倚仗自己的作为；事情成就，却不占据功劳。行动仍在，改变的是自恃与占功的方式。","【读法】可与第二章为而不恃、功成弗居相参。不处取不占居其功，不是说完成后便放弃应负责任。"]},{id:"not-displaying-worthiness",label:"其不欲见贤",showLabel:!0,sentences:[["其不欲",{text:"见",glossary:"xian-display"},{text:"贤",glossary:"xian-better"},"。"]],note:["【白话】他不想显露自己的贤能。这一收束连着奉天下与不占功，防止又把补不足变成自我标榜。","【王弼注择要】「言唯能处盈而全虚，损存以补无」，又说「是以圣人不欲示其贤，以均天下」。","【读法】见读 xiàn，贤是贤能，与第七十五章贤于的胜过义分开。公开必要信息、接受核验，与炫示自身高明并非同一件事。"]}],n=[{id:"zhang-expand",term:"张",sense:2},{id:"yi-press-down",term:"抑",sense:1},{id:"ju-raise",term:"举",sense:1},{id:"sun-reduce",term:"损",sense:1},{id:"feng-offer",term:"奉",sense:1},{id:"shi-rely",term:"恃",sense:1},{id:"chu-dwell",term:"处",sense:3},{id:"xian-display",term:"见",sense:1},{id:"xian-better",term:"贤",sense:2}];return(m,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十七章",tabindex:"-1"},[s("道德经第七十七章 "),a("a",{class:"header-anchor",href:"#道德经第七十七章","aria-label":'Permalink to "道德经第七十七章"'},"​")],-1)),r(i,{title:"有余与不足，为什么会朝相反方向流动",summary:"张弓之喻先调整高低，再说天道损有余而补不足；人之道却可能从不足者处取用，奉养有余者。结尾追问谁能以有余奉天下，并以不自恃、不占功、不显贤收束，焦点不只是个人节制，也在供给朝向谁。",points:[{label:"先读",text:"将高低、余缺两组动作对应起来，先读张弓之象。"},{label:"再辨",text:"天之道与人之道的方向相反，留意两处奉的对象。"},{label:"后看",text:"不恃、不处、不见贤连读，说明有道者怎样使用有余。"}],hint:"抑读 yì，奉读 fèng，恃读 shì，处读 chǔ，见贤的见读 xiàn，指显露自身贤能。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:o,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"天之道，损有余而补不足。",tone:"看供给方向",guide:"有余流向不足，承接张弓之象。"},{text:"人之道则不然，损不足以奉有余。",tone:"看反向取用",guide:"不要只谈平均，先问谁被减损、谁受供养。"},{text:"孰能有余以奉天下？唯有道者。",tone:"把有余转为供给",guide:"后面的不恃、不处、不见贤说明如何奉天下。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-张弓究竟引出了什么" tabindex="-1">象：张弓究竟引出了什么？ <a class="header-anchor" href="#象-张弓究竟引出了什么" aria-label="Permalink to &quot;象：张弓究竟引出了什么？&quot;">​</a></h3><p>它给出高低相调、余缺相补的形象，接着用来反观人间取用。把比喻和论旨接起来，才看得见人之道则不然的转折。</p><h3 id="理-不见贤与补不足有什么关系" tabindex="-1">理：不见贤与补不足有什么关系？ <a class="header-anchor" href="#理-不见贤与补不足有什么关系" aria-label="Permalink to &quot;理：不见贤与补不足有什么关系？&quot;">​</a></h3><p>王注以不欲示其贤、以均天下相连。若供给最终只为积累自己的优越名位，行动的中心便又回到一己；结尾因此回收自恃与占功。</p><h3 id="用-今天相参时先问什么" tabindex="-1">用：今天相参时先问什么？ <a class="header-anchor" href="#用-今天相参时先问什么" aria-label="Permalink to &quot;用：今天相参时先问什么？&quot;">​</a></h3><p>先看资源、机会与风险实际流向谁，再说明自己的调整依据。经文能提供问题意识，具体分配是否公平仍要结合处境、信息和参与者判断。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>沿实际流向检查分配。</strong> 比较名义安排与实际承担，留意资源不足者是否仍在承担更多成本。补不足应能说清所补的具体缺口。</p><p><strong>让帮助接受核验。</strong> 把目的、投入和结果交代清楚，并给反馈留下空间；贡献可以确认，却不必变成不可质疑的个人功德。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我参与的安排，究竟在补谁的不足？当我有所贡献时，是否又期待用它证明自己更高明？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与古注据卷四 010a–010b 电子录文核对。</li><li>正文、标点与别名沿本站保留，据所列卷页核对。</li><li>张弓为比喻，天人对照及王注无私、均天下另列，不补成现代自然或经济定律。</li><li>见读 xiàn，贤取贤能义；节引只取录文可明确辨读的部分，不猜改个别难读连文。</li><li>古注节引转简体并加标点，尚未逐字核对影印；白话、古注与现代启发分层。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，010a–010b</a>。</p>',15))])}}});export{y as __pageData,_ as default};
